class DB{
 static Future<List<Map<String,dynamic>>> files()async{final p=await SharedPreferences.getInstance();final raw=p.getString('files')??'[]';final a=jsonDecode(raw) as List;return a.map((e)=>Map<String,dynamic>.from(e)).toList();}
 static Future<void> saveFiles(List<Map<String,dynamic>> a)async{final p=await SharedPreferences.getInstance();await p.setString('files',jsonEncode(a));}
 static Future<List<String>> customers()async{final p=await SharedPreferences.getInstance();return p.getStringList('customers')??[];}
 static Future<void> saveCustomers(List<String> a)async{final p=await SharedPreferences.getInstance();await p.setStringList('customers',a);}
 static Future<String> get(String k)async{final p=await SharedPreferences.getInstance();return p.getString(k)??'';}
 static Future<void> set(String k,String v)async{final p=await SharedPreferences.getInstance();await p.setString(k,v);}
}

