 @override void initState(){super.initState();final x=widget.existing??{};title=_ctl(x['title']);type=_ctl(x['type']??'آپارتمان');deal=_ctl(x['deal']??'فروش');area=_ctl(x['area']);price=_ctl(x['price']);address=_ctl(x['address']);owner=_ctl(x['ownerName']);phone=_ctl(x['ownerPhone']);description=_ctl(x['description']);link=_ctl(x['divarLink']);apiKey=TextEditingController();accessToken=TextEditingController();}
