 Future<void> importDivar()async{final token=tokenFromLink();if(token==null){setState(()=>message='لینک دیوار معتبر نیست');return;}if(apiKey.text.trim().isEmpty){setState(()=>message='API Key رسمی دیوار را وارد کن');return;}setState(()=>loading=true);try{final r=await http.get(Uri.parse('https://open-api.divar.ir/v1/open-platform/finder/post/$token'),headers:{'x-api-key':apiKey.text.trim()});final j=jsonDecode(r.body);if(r.statusCode<200||r.statusCode>299)throw Exception(j['message']??r.statusCode);final d=Map<String,dynamic>.from(j['data']??{});final p=d['price'];final imgs=d['images'] is List?(d['images'] as List).map((e)=>'$e').toList():<String>[];title.text='${d['title']??d['prefilled_title']??''}';area.text='${d['size']??d['area']??''}';price.text=p is Map?'${p['value']??''}':'${p??''}';address.text='${j['address']??j['district']??address.text}';description.text='${d['description']??''}';await DB.set('pending_images',jsonEncode(imgs));setState(()=>message='اطلاعات عمومی آگهی وارد شد. شماره خصوصی مالک در GET_POST دیوار ارائه نمی‌شود.');}catch(e){setState(()=>message='خطا در دریافت آگهی: $e');}finally{if(mounted)setState(()=>loading=false);}}
