 Future<void> save()async{final all=await DB.files();final code=widget.existing==null?'MM-${DateTime.now().millisecondsSinceEpoch.toString().substring(6)}':'${widget.existing!['code']}';final im=await DB.get('pending_images');final x=<String,dynamic>{'code':code,'title':title.text,'type':type.text,'deal':deal.text,'area':area.text,'price':price.text,'address':address.text,'ownerName':owner.text,'ownerPhone':phone.text,'description':description.text,'divarLink':link.text,'images':im.isEmpty?<String>[]:jsonDecode(im),'updated':DateFormat('yyyy/MM/dd HH:mm').format(DateTime.now())};final index=all.indexWhere((e)=>e['code']==code);if(index<0)all.add(x);else all[index]=x;await DB.saveFiles(all);if(phone.text.trim().isNotEmpty){final cs=await DB.customers();if(!cs.contains(phone.text.trim())){cs.add(phone.text.trim());await DB.saveCustomers(cs);}}widget.onSaved();if(mounted)Navigator.pop(context);}
